import json
import os
HERE=os.path.dirname(os.path.abspath(__file__))
exec(open(os.path.join(HERE,'run_tests.py')).read().split('with sync_playwright()')[0])
from playwright.sync_api import sync_playwright
def preparar(pg, jug=('Beto','Ana')):
    pg.goto(APP); pg.wait_for_timeout(500)
    pg.fill('#authEmail','dir@test.mx'); pg.fill('#authPass','secreto123'); pg.click('#linkAuthModo'); pg.click('#btnAuth'); pg.wait_for_timeout(500)
    pg.evaluate("(()=>{__mock.S.t.codigos_alta=[{codigo:'ALTA1'}];localStorage.setItem('__mockdb',JSON.stringify(__mock.S))})()")
    pg.fill('#onbCodigoAlta','alta1'); pg.fill('#onbNombreAcademia','Acad'); pg.click('#formCrearAcademia button'); pg.wait_for_timeout(900)
    pg.click('#btnNuevoEquipo'); pg.wait_for_timeout(800)
    pg.evaluate("""(js)=>{const t=getTeam();js.forEach(n=>t.jugadores.push({id:nuevoId(),nombre:n,tel:'5216181234567',anio:2015,estado:'activo',consentimiento:{id:nuevoId(),tutor:'T',version:'v1',via:'presencial',fecha:new Date().toISOString()}}));
      t.entrenos.push({id:nuevoId(),fecha:'2026-11-02',hora:'17:00',lugar:'Campo',notas:'',rec:false});save();renderAll()}""",list(jug))
    pg.wait_for_timeout(1500)
with sync_playwright() as p:
    b=p.chromium.launch(); ctx,pg=nuevo(b); preparar(pg)
    pg.evaluate("document.querySelector('[data-tab=calendario]').click()")
    pg.click('#listaEntrenos button:has-text("Asistencia")'); pg.wait_for_selector('#dlg[open]')
    ok('el diálogo lista a los 2 jugadores, marcados por defecto', pg.locator('#dlg input[type=checkbox]').count()==2 and pg.locator('#dlg input[type=checkbox]:checked').count()==2)
    pg.locator('#dlg input[type=checkbox]').nth(1).uncheck(); pg.click('#dlg button:has-text("Guardar")'); pg.wait_for_timeout(1800)
    e=pg.evaluate("getTeam().entrenos[0].asistencia")
    ok('quedan 2 registros: 1 asistió, 1 no', len(e)==2 and sum(1 for a in e if a['asistio'])==1)
    ok('el entreno muestra 1/2', '1/2' in pg.inner_text('#listaEntrenos'))
    ok('subió a la nube', pg.evaluate("(__mock.S.t.asistencias||[]).length")==2)
    pg.evaluate("document.querySelector('[data-tab=plantilla]').click()")
    txt=pg.inner_text('#listaPlantilla'); ok('plantilla muestra el porcentaje por jugador', '100%' in txt and '0%' in txt, txt.replace('\n',' | ')[:200])
    ids1=sorted(a['id'] for a in e)
    pg.evaluate("document.querySelector('[data-tab=calendario]').click()")
    pg.click('#listaEntrenos button:has-text("Asistencia")'); pg.wait_for_selector('#dlg[open]'); pg.click('#dlg button:has-text("Todos")'); pg.click('#dlg button:has-text("Guardar")'); pg.wait_for_timeout(1800)
    e2=pg.evaluate("getTeam().entrenos[0].asistencia")
    ok('al corregir se reutilizan los mismos ids (no se duplican)', sorted(a['id'] for a in e2)==ids1 and all(a['asistio'] for a in e2) and pg.evaluate("__mock.S.t.asistencias.length")==2 and pg.evaluate("__mock.S.t.asistencias.every(a=>a.asistio)"))
    # baja: su historial se respeta
    pg.evaluate("document.querySelector('[data-tab=plantilla]').click()")
    pg.evaluate("window.__manual=false")
    pg.click('#listaPlantilla li:has-text("Ana") button[title^="Dar de baja"]'); pg.wait_for_timeout(1500)
    pg.evaluate("document.querySelector('[data-tab=calendario]').click()")
    pg.click('#listaEntrenos button:has-text("Asistencia")'); pg.wait_for_selector('#dlg[open]')
    ok('el diálogo ya no lista a quien está de baja', pg.locator('#dlg input[type=checkbox]').count()==1)
    pg.click('#dlg button:has-text("Ninguno")'); pg.click('#dlg button:has-text("Guardar")'); pg.wait_for_timeout(1800)
    e3=pg.evaluate("getTeam().entrenos[0].asistencia")
    ok('el registro del jugador de baja se conserva', len(e3)==2 and pg.evaluate("__mock.S.t.asistencias.length")==2)
    # eliminar definitivamente: la asistencia se va con él y no rompe la sincronización
    pg.evaluate("(()=>{const t=getTeam();t.jugadores=t.jugadores.filter(j=>j.nombre!=='Ana');save();renderAll()})()"); pg.wait_for_timeout(1800)
    ok('al eliminar al jugador se borra su asistencia y se sigue sincronizando', pg.evaluate("__mock.S.t.asistencias.length")==1 and 'No se pudo' not in pg.inner_text('#estadoSync'))
    # eliminar entreno
    pg.evaluate("(()=>{const t=getTeam();t.entrenos=[];save();renderAll()})()"); pg.wait_for_timeout(1800)
    ok('al borrar el entreno se borra su asistencia', pg.evaluate("__mock.S.t.asistencias.length")==0 and pg.evaluate("__mock.S.t.entrenos.length")==0)
    # padre ve el % de su hijo
    pg.evaluate("""(()=>{const t=getTeam();const j=t.jugadores[0];window.__j=j.id;t.entrenos.push({id:nuevoId(),fecha:'2026-11-03',hora:'17:00',lugar:'C',notas:'',rec:false,asistencia:[{id:nuevoId(),jugadorId:j.id,asistio:true}]});
      t.entrenos.push({id:nuevoId(),fecha:'2026-11-04',hora:'17:00',lugar:'C',notas:'',rec:false,asistencia:[{id:nuevoId(),jugadorId:j.id,asistio:false}]});save();renderAll()})()"""); pg.wait_for_timeout(1800)
    pg.evaluate("document.querySelector('[data-tab=plantilla]').click()")
    pg.click('#listaPlantilla button[title^="Invitar"]'); pg.wait_for_timeout(1500)
    code=pg.evaluate("__mock.S.t.invitaciones.slice(-1)[0].codigo"); pg.keyboard.press('Escape')
    seed=json.dumps(json.dumps({**pg.evaluate("__mock.S"),"session":None}))
    ctx2,pg2=nuevo(b); pg2.add_init_script("localStorage.getItem('__mockdb')||localStorage.setItem('__mockdb',%s)"%seed)
    pg2.goto(APP); pg2.wait_for_timeout(500)
    pg2.fill('#authEmail','mama@test.mx'); pg2.fill('#authPass','secreto123'); pg2.click('#linkAuthModo'); pg2.click('#btnAuth'); pg2.wait_for_timeout(600)
    pg2.fill('#onbCodigo',code); pg2.click('#formCodigo button'); pg2.wait_for_timeout(1000)
    ptxt=pg2.inner_text('#contenidoPadre'); ok('el padre ve la asistencia de su hijo', 'Asistencia a entrenamientos' in ptxt and '50%' in ptxt and '1 de 2' in ptxt, ptxt[:200].replace('\n',' | '))
    # ---- sin el parche 03 en la base
    ctx3,pg3=nuevo(b); pg3.add_init_script("localStorage.setItem('__missing','asistencias')")
    preparar(pg3) if False else None
    pg3.goto(APP); pg3.wait_for_timeout(500)
    pg3.fill('#authEmail','dir3@test.mx'); pg3.fill('#authPass','secreto123'); pg3.click('#linkAuthModo'); pg3.click('#btnAuth'); pg3.wait_for_timeout(500)
    pg3.evaluate("(()=>{__mock.S.t.codigos_alta=[{codigo:'ALTA9'}];localStorage.setItem('__mockdb',JSON.stringify(__mock.S))})()")
    pg3.fill('#onbCodigoAlta','alta9'); pg3.fill('#onbNombreAcademia','Sin parche'); pg3.click('#formCrearAcademia button'); pg3.wait_for_timeout(900)
    ok('sin la tabla de asistencia la app igual abre', pg3.evaluate("document.body.dataset.modo")=='staff')
    pg3.click('#btnNuevoEquipo'); pg3.wait_for_timeout(800)
    pg3.evaluate("(()=>{const t=getTeam();t.jugadores.push({id:nuevoId(),nombre:'X',tel:'1',anio:2015,estado:'activo'});t.entrenos.push({id:nuevoId(),fecha:'2026-11-02',hora:'17:00',lugar:'C',notas:'',rec:false});save();renderAll()})()"); pg3.wait_for_timeout(1800)
    ok('lo demás sí se guarda en la nube', pg3.evaluate("__mock.S.t.entrenos.length")==1 and pg3.evaluate("__mock.S.t.jugadores.length")==1 and 'No se pudo' not in pg3.inner_text('#estadoSync'))
    pg3.evaluate("window.__manual=true"); pg3.evaluate("document.querySelector('[data-tab=calendario]').click()")
    pg3.click('#listaEntrenos button:has-text("Asistencia")'); pg3.wait_for_selector('dialog.dlg-ui[open]')
    ok('avisa que falta actualizar la base', 'parche 03' in pg3.inner_text('dialog.dlg-ui .dlg-ui-msg'))
    b.close()
print('ERRORES JS:',[e for e in errors if 'NATIVO' in e or 'pageerror' in e or not e.startswith('console:')]); print('RESUMEN: %d/%d'%(sum(1 for _,c in res if c),len(res)))
